-- 17: derived statistics, history-v1. Run entire file; Write Changes after success.
-- Counts with no historical evidence (returns, exact possession time, conversions) stay NULL.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_17;
CREATE TEMP TABLE afl_stats_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_stats_prerequisites BEFORE INSERT ON afl_stats_guard BEGIN
 SELECT CASE WHEN (SELECT count(*) FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258'))<>9575 OR
 (SELECT count(*) FROM play_details WHERE play_id IN (SELECT id FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258')))<>9575 OR
 (SELECT count(*) FROM play_line_matchups WHERE play_id IN (SELECT id FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258')))<>32343
 THEN RAISE(ROLLBACK,'Import complete plays and line matchups (12-15) first') END;
 SELECT CASE WHEN (SELECT count(*) FROM play_participants WHERE play_id IN (SELECT id FROM plays WHERE game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258')))<>23811
 THEN RAISE(ROLLBACK,'Import complete participants (14) first') END;
END;
INSERT INTO afl_stats_guard VALUES(1);
CREATE TEMP TABLE afl_delta_input AS
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'carries' AS metric_key,(1) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='runner' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.play_type='Run' AND coalesce(p.is_sack,0)=0)
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'rushing_yards' AS metric_key,(p.yards) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='runner' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.play_type='Run' AND coalesce(p.is_sack,0)=0)
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'longest_rush' AS metric_key,(p.yards) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='runner' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.play_type='Run' AND coalesce(p.is_sack,0)=0)
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'rushing_touchdowns' AS metric_key,(1) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='runner' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.is_touchdown=1 AND p.play_type='Run')
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'rushing_first_downs' AS metric_key,(1) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='runner' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.is_first_down=1 AND p.play_type='Run')
