SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'tackles_for_loss' AS metric_key,(1) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='tackler' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.yards<0 OR p.is_sack=1 OR p.defense_result='TFL')
