SELECT p.id AS play_id,m.offense_player_id AS player_id,m.offense_team_id AS team_id,'ol_wins' AS metric_key,(1) AS amount FROM plays p JOIN play_line_matchups m ON m.play_id=p.id WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (m.offense_player_id IS NOT NULL AND m.winner_side='OL')
UNION ALL
SELECT p.id AS play_id,m.offense_player_id AS player_id,m.offense_team_id AS team_id,'ol_losses' AS metric_key,(1) AS amount FROM plays p JOIN play_line_matchups m ON m.play_id=p.id WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (m.offense_player_id IS NOT NULL AND m.winner_side='DL')
UNION ALL
SELECT p.id AS play_id,m.defense_player_id AS player_id,m.defense_team_id AS team_id,'dl_wins' AS metric_key,(1) AS amount FROM plays p JOIN play_line_matchups m ON m.play_id=p.id WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (m.defense_player_id IS NOT NULL AND m.winner_side='DL')
UNION ALL
SELECT p.id AS play_id,m.defense_player_id AS player_id,m.defense_team_id AS team_id,'dl_losses' AS metric_key,(1) AS amount FROM plays p JOIN play_line_matchups m ON m.play_id=p.id WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (m.defense_player_id IS NOT NULL AND m.winner_side='OL')
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'jukes' AS metric_key,(d.jukes) AS amount FROM plays p JOIN play_details d ON d.play_id=p.id JOIN play_participants a ON a.play_id=p.id AND ((a.role='runner' AND p.play_type='Run') OR (a.role='target' AND p.is_complete=1)) WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (a.player_id IS NOT NULL AND d.jukes IS NOT NULL AND d.jukes>0)
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'broken_tackles' AS metric_key,(d.broken_tackles) AS amount FROM plays p JOIN play_details d ON d.play_id=p.id JOIN play_participants a ON a.play_id=p.id AND ((a.role='runner' AND p.play_type='Run') OR (a.role='target' AND p.is_complete=1)) WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (a.player_id IS NOT NULL AND d.broken_tackles IS NOT NULL AND d.broken_tackles>0)
UNION ALL
SELECT p.id AS play_id,a.player_id AS player_id,a.team_id AS team_id,'safeties_forced' AS metric_key,(1) AS amount FROM plays p JOIN play_participants a ON a.play_id=p.id AND a.role='tackler' AND a.player_id IS NOT NULL WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.is_safety=1)
UNION ALL
SELECT p.id AS play_id,NULL AS player_id,p.offense_team_id AS team_id,'carries' AS metric_key,(1) AS amount FROM plays p  WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.play_type='Kneel')
UNION ALL
SELECT p.id AS play_id,NULL AS player_id,p.offense_team_id AS team_id,'rushing_yards' AS metric_key,(p.yards) AS amount FROM plays p  WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.play_type='Kneel')
UNION ALL
SELECT p.id AS play_id,NULL AS player_id,p.offense_team_id AS team_id,'passing_attempts' AS metric_key,(1) AS amount FROM plays p  WHERE p.game_id IN (SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') AND (p.play_type='Spike');
CREATE TEMP TABLE afl_expected_deltas AS
SELECT play_id||'|'||coalesce(player_id,'TEAM')||'|'||team_id||'|'||metric_key AS id,
 play_id,player_id,team_id,metric_key,sum(amount) AS amount,'history-v1' AS calculation_version
FROM afl_delta_input GROUP BY play_id,player_id,team_id,metric_key;
CREATE TEMP TABLE afl_observed_players AS
SELECT DISTINCT p.game_id,a.player_id,a.team_id FROM play_participants a JOIN plays p ON p.id=a.play_id WHERE a.player_id IS NOT NULL
UNION SELECT DISTINCT p.game_id,m.offense_player_id,m.offense_team_id FROM play_line_matchups m JOIN plays p ON p.id=m.play_id WHERE m.offense_player_id IS NOT NULL
UNION SELECT DISTINCT p.game_id,m.defense_player_id,m.defense_team_id FROM play_line_matchups m JOIN plays p ON p.id=m.play_id WHERE m.defense_player_id IS NOT NULL;
CREATE TEMP TABLE afl_expected_player_stats AS
SELECT o.game_id,o.player_id,o.team_id,coalesce(sum(CASE WHEN d.metric_key='carries' THEN d.amount ELSE 0 END),0) AS carries,coalesce(sum(CASE WHEN d.metric_key='rushing_yards' THEN d.amount ELSE 0 END),0) AS rushing_yards,coalesce(sum(CASE WHEN d.metric_key='rushing_touchdowns' THEN d.amount ELSE 0 END),0) AS rushing_touchdowns,coalesce(sum(CASE WHEN d.metric_key='rushing_fumbles' THEN d.amount ELSE 0 END),0) AS rushing_fumbles,coalesce(sum(CASE WHEN d.metric_key='rushing_fumbles_lost' THEN d.amount ELSE 0 END),0) AS rushing_fumbles_lost,coalesce(sum(CASE WHEN d.metric_key='rushing_first_downs' THEN d.amount ELSE 0 END),0) AS rushing_first_downs,coalesce(sum(CASE WHEN d.metric_key='jukes' THEN d.amount ELSE 0 END),0) AS jukes,coalesce(sum(CASE WHEN d.metric_key='broken_tackles' THEN d.amount ELSE 0 END),0) AS broken_tackles,coalesce(sum(CASE WHEN d.metric_key='negative_rushes' THEN d.amount ELSE 0 END),0) AS negative_rushes,coalesce(sum(CASE WHEN d.metric_key='rushes_5_plus' THEN d.amount ELSE 0 END),0) AS rushes_5_plus,coalesce(sum(CASE WHEN d.metric_key='rushes_10_plus' THEN d.amount ELSE 0 END),0) AS rushes_10_plus,coalesce(sum(CASE WHEN d.metric_key='rushes_20_plus' THEN d.amount ELSE 0 END),0) AS rushes_20_plus,coalesce(sum(CASE WHEN d.metric_key='rushes_30_plus' THEN d.amount ELSE 0 END),0) AS rushes_30_plus,coalesce(sum(CASE WHEN d.metric_key='rushes_50_plus' THEN d.amount ELSE 0 END),0) AS rushes_50_plus,max(CASE WHEN d.metric_key='longest_rush' THEN d.amount END) AS longest_rush,coalesce(sum(CASE WHEN d.metric_key='ol_wins' THEN d.amount ELSE 0 END),0) AS ol_wins,coalesce(sum(CASE WHEN d.metric_key='ol_losses' THEN d.amount ELSE 0 END),0) AS ol_losses,coalesce(sum(CASE WHEN d.metric_key='lead_blocks' THEN d.amount ELSE 0 END),0) AS lead_blocks,coalesce(sum(CASE WHEN d.metric_key='dl_wins' THEN d.amount ELSE 0 END),0) AS dl_wins,coalesce(sum(CASE WHEN d.metric_key='dl_losses' THEN d.amount ELSE 0 END),0) AS dl_losses,coalesce(sum(CASE WHEN d.metric_key='tackles' THEN d.amount ELSE 0 END),0) AS tackles,coalesce(sum(CASE WHEN d.metric_key='tackles_for_loss' THEN d.amount ELSE 0 END),0) AS tackles_for_loss,coalesce(sum(CASE WHEN d.metric_key='defensive_sacks' THEN d.amount ELSE 0 END),0) AS defensive_sacks,coalesce(sum(CASE WHEN d.metric_key='forced_fumbles' THEN d.amount ELSE 0 END),0) AS forced_fumbles,coalesce(sum(CASE WHEN d.metric_key='fumble_recoveries' THEN d.amount ELSE 0 END),0) AS fumble_recoveries,coalesce(sum(CASE WHEN d.metric_key='defensive_interceptions' THEN d.amount ELSE 0 END),0) AS defensive_interceptions,coalesce(sum(CASE WHEN d.metric_key='deflections' THEN d.amount ELSE 0 END),0) AS deflections,NULL AS fumble_return_yards,NULL AS fumble_return_touchdowns,NULL AS interception_return_yards,NULL AS interception_return_touchdowns,coalesce(sum(CASE WHEN d.metric_key='safeties_forced' THEN d.amount ELSE 0 END),0) AS safeties_forced,coalesce(sum(CASE WHEN d.metric_key='targets' THEN d.amount ELSE 0 END),0) AS targets,coalesce(sum(CASE WHEN d.metric_key='receptions' THEN d.amount ELSE 0 END),0) AS receptions,coalesce(sum(CASE WHEN d.metric_key='receiving_yards' THEN d.amount ELSE 0 END),0) AS receiving_yards,coalesce(sum(CASE WHEN d.metric_key='receiving_touchdowns' THEN d.amount ELSE 0 END),0) AS receiving_touchdowns,coalesce(sum(CASE WHEN d.metric_key='receiving_first_downs' THEN d.amount ELSE 0 END),0) AS receiving_first_downs,coalesce(sum(CASE WHEN d.metric_key='receiving_fumbles' THEN d.amount ELSE 0 END),0) AS receiving_fumbles,coalesce(sum(CASE WHEN d.metric_key='receiving_fumbles_lost' THEN d.amount ELSE 0 END),0) AS receiving_fumbles_lost,coalesce(sum(CASE WHEN d.metric_key='yac' THEN d.amount ELSE 0 END),0) AS yac,max(CASE WHEN d.metric_key='longest_reception' THEN d.amount END) AS longest_reception,coalesce(sum(CASE WHEN d.metric_key='receptions_20_plus' THEN d.amount ELSE 0 END),0) AS receptions_20_plus,coalesce(sum(CASE WHEN d.metric_key='passing_attempts' THEN d.amount ELSE 0 END),0) AS passing_attempts,coalesce(sum(CASE WHEN d.metric_key='passing_completions' THEN d.amount ELSE 0 END),0) AS passing_completions,coalesce(sum(CASE WHEN d.metric_key='passing_yards' THEN d.amount ELSE 0 END),0) AS passing_yards,coalesce(sum(CASE WHEN d.metric_key='passing_touchdowns' THEN d.amount ELSE 0 END),0) AS passing_touchdowns,coalesce(sum(CASE WHEN d.metric_key='interceptions_thrown' THEN d.amount ELSE 0 END),0) AS interceptions_thrown,coalesce(sum(CASE WHEN d.metric_key='sacks_taken' THEN d.amount ELSE 0 END),0) AS sacks_taken,coalesce(sum(CASE WHEN d.metric_key='sack_yards_lost' THEN d.amount ELSE 0 END),0) AS sack_yards_lost,max(CASE WHEN d.metric_key='longest_pass' THEN d.amount END) AS longest_pass,1 AS participation_verified,
 '{"participation":"observed event/line roles only; not a reconstructed full-game roster","spikes_and_kneels":"team-only if no QB identity recorded","supported":["broken_tackles","carries","defensive_interceptions","defensive_sacks","deflections","dl_losses","dl_wins","forced_fumbles","fumble_recoveries","interceptions_thrown","jukes","lead_blocks","longest_pass","longest_reception","longest_rush","negative_rushes","ol_losses","ol_wins","passing_attempts","passing_completions","passing_touchdowns","passing_yards","receiving_first_downs","receiving_fumbles","receiving_fumbles_lost","receiving_touchdowns","receiving_yards","receptions","receptions_20_plus","rushes_10_plus","rushes_20_plus","rushes_30_plus","rushes_50_plus","rushes_5_plus","rushing_first_downs","rushing_fumbles","rushing_fumbles_lost","rushing_touchdowns","rushing_yards","sack_yards_lost","sacks_taken","safeties_forced","tackles","tackles_for_loss","targets","yac"],"unknown":["fumble_return_touchdowns","fumble_return_yards","interception_return_touchdowns","interception_return_yards"],"version":"history-v1"}' AS metric_availability_json,
 'history-v1' AS calculation_version,s.version AS source_game_version
FROM afl_observed_players o JOIN games g ON g.id=o.game_id JOIN game_state s ON s.game_id=g.id
LEFT JOIN plays p ON p.game_id=o.game_id
LEFT JOIN afl_expected_deltas d ON d.play_id=p.id AND d.player_id=o.player_id AND d.team_id=o.team_id
WHERE g.season_id='97808f43-a0d5-5251-bf8d-fae1643c8258' GROUP BY o.game_id,o.player_id,o.team_id,s.version;
CREATE TEMP TABLE afl_expected_team_stats AS
SELECT r.game_id,r.team_id,r.opponent_team_id,sum(p.play_type IN ('Run','Pass','Kneel','Spike')) AS plays,
NULL AS drives,
sum(coalesce(p.is_first_down,0)) AS first_downs,
sum(p.play_type IN ('Run','Kneel') AND coalesce(p.is_sack,0)=0) AS rushing_attempts,
sum(CASE WHEN p.play_type IN ('Run','Kneel') AND coalesce(p.is_sack,0)=0 THEN p.yards ELSE 0 END) AS rushing_yards,
sum(p.play_type='Run' AND p.is_touchdown=1) AS rushing_touchdowns,
sum(p.play_type IN ('Pass','Spike') AND coalesce(p.is_sack,0)=0) AS passing_attempts,
sum(p.play_type='Pass' AND p.is_complete=1 AND coalesce(p.is_sack,0)=0) AS passing_completions,
sum(CASE WHEN p.play_type='Pass' AND p.is_complete=1 AND coalesce(p.is_sack,0)=0 THEN p.yards ELSE 0 END) AS passing_yards,
sum(p.play_type='Pass' AND p.is_complete=1 AND p.is_touchdown=1) AS passing_touchdowns,
sum(coalesce(p.is_sack,0)) AS sacks_taken,
sum(CASE WHEN p.is_sack=1 THEN max(-p.yards,0) ELSE 0 END) AS sack_yards_lost,
sum(coalesce(p.turnover_type='interception',0)) AS interceptions_thrown,
sum(coalesce(p.is_fumble,0)) AS fumbles,
sum(coalesce(p.fumble_lost,0)) AS fumbles_lost,
sum(CASE WHEN p.is_complete=1 THEN coalesce(p.yac,0) ELSE 0 END) AS offensive_yac,
(SELECT sum(coalesce(x.is_sack,0)) FROM plays x WHERE x.game_id=r.game_id AND x.defense_team_id=r.team_id) AS defensive_sacks,
(SELECT count(*) FROM play_participants a JOIN plays x ON x.id=a.play_id WHERE x.game_id=r.game_id AND a.team_id=r.team_id AND a.role='tackler') AS tackles,
(SELECT count(*) FROM play_participants a JOIN plays x ON x.id=a.play_id WHERE x.game_id=r.game_id AND a.team_id=r.team_id AND a.role='tackler' AND (x.yards<0 OR x.is_sack=1 OR x.defense_result='TFL')) AS tackles_for_loss,
(SELECT count(*) FROM plays x WHERE x.game_id=r.game_id AND x.defense_team_id=r.team_id AND x.turnover_type='interception') AS interceptions_made,
(SELECT count(*) FROM plays x WHERE x.game_id=r.game_id AND x.defense_team_id=r.team_id AND x.fumble_lost=1) AS fumbles_recovered,
(SELECT count(*) FROM play_participants a JOIN plays x ON x.id=a.play_id WHERE x.game_id=r.game_id AND a.team_id=r.team_id AND a.role='deflector') AS deflections,
(SELECT count(*) FROM plays x WHERE x.game_id=r.game_id AND x.defense_team_id=r.team_id AND x.is_safety=1) AS safeties_forced,
sum(p.play_type='Field Goal') AS field_goal_attempts,
sum(p.play_type='Field Goal' AND p.result='Kick FG') AS field_goals_made,
NULL AS extra_point_attempts,
NULL AS extra_points_made,
NULL AS two_point_attempts,
NULL AS two_points_made,
sum(p.play_type='Punt') AS punts,
NULL AS possession_seconds,
 '{"team_attempts":"Pass + Spike, excluding sacks","team_rushing":"Run + Kneel, excluding sacks","unknown":["drives","possession_seconds","extra_point_attempts","extra_points_made","two_point_attempts","two_points_made"],"version":"history-v1","yardage":"gross passing; sacks stored separately; views expose gross and net"}' AS metric_availability_json,
 'history-v1' AS calculation_version,s.version AS source_game_version
FROM team_game_results r JOIN game_state s ON s.game_id=r.game_id LEFT JOIN plays p ON p.game_id=r.game_id AND p.offense_team_id=r.team_id
WHERE r.season_id='97808f43-a0d5-5251-bf8d-fae1643c8258' GROUP BY r.game_id,r.team_id,r.opponent_team_id,s.version;
CREATE TEMP TRIGGER afl_stats_conflicts BEFORE INSERT ON afl_stats_guard BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_expected_deltas i JOIN play_stat_deltas t ON t.id=i.id WHERE t.play_id IS NOT i.play_id OR t.player_id IS NOT i.player_id OR t.team_id IS NOT i.team_id OR t.metric_key IS NOT i.metric_key OR t.amount IS NOT i.amount OR t.calculation_version IS NOT i.calculation_version) THEN RAISE(ROLLBACK,'play_stat_deltas: existing computed stats differ; reconcile before rebuild') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_expected_player_stats i JOIN player_game_stats t ON t.game_id=i.game_id AND t.player_id=i.player_id AND t.team_id=i.team_id WHERE t.carries IS NOT i.carries OR t.rushing_yards IS NOT i.rushing_yards OR t.rushing_touchdowns IS NOT i.rushing_touchdowns OR t.rushing_fumbles IS NOT i.rushing_fumbles OR t.rushing_fumbles_lost IS NOT i.rushing_fumbles_lost OR t.rushing_first_downs IS NOT i.rushing_first_downs OR t.jukes IS NOT i.jukes OR t.broken_tackles IS NOT i.broken_tackles OR t.negative_rushes IS NOT i.negative_rushes OR t.rushes_5_plus IS NOT i.rushes_5_plus OR t.rushes_10_plus IS NOT i.rushes_10_plus OR t.rushes_20_plus IS NOT i.rushes_20_plus OR t.rushes_30_plus IS NOT i.rushes_30_plus OR t.rushes_50_plus IS NOT i.rushes_50_plus OR t.longest_rush IS NOT i.longest_rush OR t.ol_wins IS NOT i.ol_wins OR t.ol_losses IS NOT i.ol_losses OR t.lead_blocks IS NOT i.lead_blocks OR t.dl_wins IS NOT i.dl_wins OR t.dl_losses IS NOT i.dl_losses OR t.tackles IS NOT i.tackles OR t.tackles_for_loss IS NOT i.tackles_for_loss OR t.defensive_sacks IS NOT i.defensive_sacks OR t.forced_fumbles IS NOT i.forced_fumbles OR t.fumble_recoveries IS NOT i.fumble_recoveries OR t.defensive_interceptions IS NOT i.defensive_interceptions OR t.deflections IS NOT i.deflections OR t.fumble_return_yards IS NOT i.fumble_return_yards OR t.fumble_return_touchdowns IS NOT i.fumble_return_touchdowns OR t.interception_return_yards IS NOT i.interception_return_yards OR t.interception_return_touchdowns IS NOT i.interception_return_touchdowns OR t.safeties_forced IS NOT i.safeties_forced OR t.targets IS NOT i.targets OR t.receptions IS NOT i.receptions OR t.receiving_yards IS NOT i.receiving_yards OR t.receiving_touchdowns IS NOT i.receiving_touchdowns OR t.receiving_first_downs IS NOT i.receiving_first_downs OR t.receiving_fumbles IS NOT i.receiving_fumbles OR t.receiving_fumbles_lost IS NOT i.receiving_fumbles_lost OR t.yac IS NOT i.yac OR t.longest_reception IS NOT i.longest_reception OR t.receptions_20_plus IS NOT i.receptions_20_plus OR t.passing_attempts IS NOT i.passing_attempts OR t.passing_completions IS NOT i.passing_completions OR t.passing_yards IS NOT i.passing_yards OR t.passing_touchdowns IS NOT i.passing_touchdowns OR t.interceptions_thrown IS NOT i.interceptions_thrown OR t.sacks_taken IS NOT i.sacks_taken OR t.sack_yards_lost IS NOT i.sack_yards_lost OR t.longest_pass IS NOT i.longest_pass OR t.participation_verified IS NOT i.participation_verified OR t.metric_availability_json IS NOT i.metric_availability_json OR t.calculation_version IS NOT i.calculation_version OR t.source_game_version IS NOT i.source_game_version) THEN RAISE(ROLLBACK,'player_game_stats: existing computed stats differ; reconcile before rebuild') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_expected_team_stats i JOIN team_game_stats t ON t.game_id=i.game_id AND t.team_id=i.team_id WHERE t.opponent_team_id IS NOT i.opponent_team_id OR t.plays IS NOT i.plays OR t.drives IS NOT i.drives OR t.first_downs IS NOT i.first_downs OR t.rushing_attempts IS NOT i.rushing_attempts OR t.rushing_yards IS NOT i.rushing_yards OR t.rushing_touchdowns IS NOT i.rushing_touchdowns OR t.passing_attempts IS NOT i.passing_attempts OR t.passing_completions IS NOT i.passing_completions OR t.passing_yards IS NOT i.passing_yards OR t.passing_touchdowns IS NOT i.passing_touchdowns OR t.sacks_taken IS NOT i.sacks_taken OR t.sack_yards_lost IS NOT i.sack_yards_lost OR t.interceptions_thrown IS NOT i.interceptions_thrown OR t.fumbles IS NOT i.fumbles OR t.fumbles_lost IS NOT i.fumbles_lost OR t.offensive_yac IS NOT i.offensive_yac OR t.defensive_sacks IS NOT i.defensive_sacks OR t.tackles IS NOT i.tackles OR t.tackles_for_loss IS NOT i.tackles_for_loss OR t.interceptions_made IS NOT i.interceptions_made OR t.fumbles_recovered IS NOT i.fumbles_recovered OR t.deflections IS NOT i.deflections OR t.safeties_forced IS NOT i.safeties_forced OR t.field_goal_attempts IS NOT i.field_goal_attempts OR t.field_goals_made IS NOT i.field_goals_made OR t.extra_point_attempts IS NOT i.extra_point_attempts OR t.extra_points_made IS NOT i.extra_points_made OR t.two_point_attempts IS NOT i.two_point_attempts OR t.two_points_made IS NOT i.two_points_made OR t.punts IS NOT i.punts OR t.possession_seconds IS NOT i.possession_seconds OR t.metric_availability_json IS NOT i.metric_availability_json OR t.calculation_version IS NOT i.calculation_version OR t.source_game_version IS NOT i.source_game_version) THEN RAISE(ROLLBACK,'team_game_stats: existing computed stats differ; reconcile before rebuild') END;
