INSERT INTO afl_stats_guard VALUES(2);
INSERT INTO play_stat_deltas (id, play_id, player_id, team_id, metric_key, amount, calculation_version) SELECT i.id, i.play_id, i.player_id, i.team_id, i.metric_key, i.amount, i.calculation_version FROM afl_expected_deltas i WHERE NOT EXISTS(SELECT 1 FROM play_stat_deltas t WHERE t.id=i.id);
