INSERT INTO team_game_stats (game_id, team_id, opponent_team_id, plays, drives, first_downs, rushing_attempts, rushing_yards, rushing_touchdowns, passing_attempts, passing_completions, passing_yards, passing_touchdowns, sacks_taken, sack_yards_lost, interceptions_thrown, fumbles, fumbles_lost, offensive_yac, defensive_sacks, tackles, tackles_for_loss, interceptions_made, fumbles_recovered, deflections, safeties_forced, field_goal_attempts, field_goals_made, extra_point_attempts, extra_points_made, two_point_attempts, two_points_made, punts, possession_seconds, metric_availability_json, calculation_version, source_game_version) SELECT i.game_id, i.team_id, i.opponent_team_id, i.plays, i.drives, i.first_downs, i.rushing_attempts, i.rushing_yards, i.rushing_touchdowns, i.passing_attempts, i.passing_completions, i.passing_yards, i.passing_touchdowns, i.sacks_taken, i.sack_yards_lost, i.interceptions_thrown, i.fumbles, i.fumbles_lost, i.offensive_yac, i.defensive_sacks, i.tackles, i.tackles_for_loss, i.interceptions_made, i.fumbles_recovered, i.deflections, i.safeties_forced, i.field_goal_attempts, i.field_goals_made, i.extra_point_attempts, i.extra_points_made, i.two_point_attempts, i.two_points_made, i.punts, i.possession_seconds, i.metric_availability_json, i.calculation_version, i.source_game_version FROM afl_expected_team_stats i WHERE NOT EXISTS(SELECT 1 FROM team_game_stats t WHERE t.game_id=i.game_id AND t.team_id=i.team_id);
INSERT INTO import_batches(id,source_filename,source_sha256,importer_version,status,counts_json,reconciliation_json,imported_at) SELECT '34575b7f-cc85-5ae9-9a70-9450591adc49','Football Game DB spreadsheet (1).xlsx','ea9f4319219b46711d28143c90ab27a9fd5ba80b0ade895a2aebf6516c59b704','remaining-snapshot-v1-17-derived-statistics','imported',json_object('play_stat_deltas',(SELECT count(*) FROM afl_expected_deltas),'player_game_stats',(SELECT count(*) FROM afl_expected_player_stats),'team_game_stats',(SELECT count(*) FROM afl_expected_team_stats)),'{"policy":"history-v1; structured roles and line JSON; unknowns NULL; no PlayerTeams historical attribution"}',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NOT EXISTS(SELECT 1 FROM import_batches WHERE id='34575b7f-cc85-5ae9-9a70-9450591adc49');
