SELECT 'player_game_stats' AS imported_table,count(*) AS records FROM player_game_stats WHERE game_id IN(SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258') UNION ALL SELECT 'team_game_stats',count(*) FROM team_game_stats WHERE game_id IN(SELECT id FROM games WHERE season_id='97808f43-a0d5-5251-bf8d-fae1643c8258');
